create schema if not exists private;
grant usage on schema private to fund_admin, expert, applicant;

create function private.claims() returns json language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims', true),''),'{}')::json $$;
create function private.login() returns text language sql stable as $$ select private.claims()->>'login' $$;
create function private.jwt_role() returns text language sql stable as $$ select private.claims()->>'role' $$;
create function private.via() returns text language sql stable as $$
 select case when lower(coalesce((nullif(current_setting('request.headers', true),'')::json)->>'x-client',''))='ai' then 'ai' else 'human' end $$;
create function private.my_company() returns int language sql stable security definer set search_path=pg_catalog,api as $$
 select company_id from api.app_user where login = private.login() $$;
create function private.company_limit(cid int) returns numeric language sql stable security definer set search_path=pg_catalog,api as $$
 select funding_limit from api.company where id=cid $$;
create function private.ord(sid int) returns int language sql stable security definer set search_path=pg_catalog,api as $$
 select ord from api.status where id=sid $$;
grant execute on all functions in schema private to fund_admin, expert, applicant;

-- constraints R6,R7
alter table api.application alter column amount set not null;
alter table api.application add constraint amount_valid check (amount <> 'NaN'::numeric and amount >= 0);
alter table api.application add constraint revenue_valid check (revenue is null or (revenue <> 'NaN'::numeric));
alter table api.application alter column status_id set default 20000;

-- audit and confirmation tables
create table api.audit(id bigserial primary key, ts timestamptz not null default now(), actor text, via text not null check (via in ('ai','human')), op text not null, app_id int);
create table api.confirmation(id bigserial primary key, actor text not null default '', op text not null check (op in ('delete','bulk_update')), app_id int, created_at timestamptz not null default now(), used boolean not null default false);
alter table api.audit enable row level security;
alter table api.confirmation enable row level security;
create policy audit_admin on api.audit for select to fund_admin using (true);
create policy conf_admin on api.confirmation for select to fund_admin using (true);
create policy conf_own_sel on api.confirmation for select to expert, applicant using (actor = private.login());
create policy conf_ins on api.confirmation for insert to fund_admin, expert, applicant with check (true);

-- triggers
create function private.conf_ins() returns trigger language plpgsql security definer set search_path=pg_catalog,api,private as $$
begin
 if private.via()='ai' then raise exception 'Подтверждение может дать только человек' using errcode='42501'; end if;
 if private.login() is null then raise exception 'нет логина' using errcode='42501'; end if;
 new.actor:=private.login(); new.used:=false; new.created_at:=now();
 if new.op='delete' and new.app_id is null then raise exception 'для delete нужен app_id'; end if;
 return new; end $$;
create trigger t_conf before insert on api.confirmation for each row execute function private.conf_ins();

create function private.use_conf(p_op text, p_app int) returns boolean language plpgsql security definer set search_path=pg_catalog,api,private as $$
declare cid bigint; begin
 select id into cid from api.confirmation where actor=private.login() and op=p_op and app_id is not distinct from p_app and not used and created_at>now()-interval '10 minutes' order by id limit 1 for update;
 if cid is null then return false; end if;
 update api.confirmation set used=true where id=cid; return true; end $$;

create function private.app_guard() returns trigger language plpgsql security definer set search_path=pg_catalog,api,private as $$
declare r text:=private.jwt_role(); oo int; no int; lim numeric; ok boolean;
begin
 no:=private.ord(new.status_id);
 if TG_OP='INSERT' then
  if no is distinct from 1 then raise exception 'Новая заявка создаётся в статусе «Черновик»' using errcode='23514'; end if;
  return new;
 end if;
 oo:=private.ord(old.status_id);
 if new.status_id is distinct from old.status_id then
  ok := (oo in (1,2) and no=oo+1) or (oo=3 and no in (4,5));
  if not ok then raise exception 'Недопустимый переход статуса' using errcode='23514'; end if;
  if r='applicant' and oo<>1 then raise exception 'Заявитель может только подать черновик' using errcode='42501'; end if;
  if r='expert' and oo not in (2,3) then raise exception 'Недопустимо для эксперта' using errcode='42501'; end if;
 end if;
 if r='expert' and new.expert is distinct from old.expert and new.expert is distinct from private.login() then
  raise exception 'Эксперт может назначить только себя' using errcode='42501'; end if;
 if no in (4,5) and coalesce(btrim(new.verdict),'')='' then
  raise exception 'Нужно заключение эксперта' using errcode='23514'; end if;
 if no=4 then
  lim:=private.company_limit(new.company_id);
  if new.amount > coalesce(lim,0) then raise exception 'Сумма превышает лимит компании' using errcode='23514'; end if;
 end if;
 return new; end $$;
create trigger t_guard before insert or update on api.application for each row execute function private.app_guard();

create function private.app_del() returns trigger language plpgsql security definer set search_path=pg_catalog,api,private as $$
begin
 if private.via()='ai' and not private.use_conf('delete', old.id) then
  raise exception 'Удаление от агента требует подтверждения человеком' using errcode='42501'; end if;
 return old; end $$;
create trigger t_del before delete on api.application for each row execute function private.app_del();

create function private.app_bulk() returns trigger language plpgsql security definer set search_path=pg_catalog,api,private as $$
begin
 if private.via()='ai' and (select count(*) from nt)>1 and not private.use_conf('bulk_update', null) then
  raise exception 'Массовая правка от агента требует подтверждения человеком' using errcode='42501'; end if;
 return null; end $$;
create trigger t_bulk after update on api.application referencing new table as nt for each statement execute function private.app_bulk();

create function private.app_audit() returns trigger language plpgsql security definer set search_path=pg_catalog,api,private as $$
begin
 insert into api.audit(actor,via,op,app_id) values (private.login(), private.via(), lower(TG_OP), coalesce(new.id, old.id));
 return null; end $$;
create trigger t_audit after insert or update or delete on api.application for each row execute function private.app_audit();

-- grants
revoke all on api.audit, api.confirmation from public, applicant, expert;
revoke truncate on api.application from fund_admin;
grant select on api.audit to fund_admin;
grant select, insert on api.confirmation to fund_admin, expert, applicant;
grant usage on all sequences in schema api to fund_admin, expert, applicant;

grant select on api.status to expert, applicant;
grant select on api.company to expert, applicant;
grant select (id,number,company_id,status_id,amount,revenue,description,verdict) on api.application to applicant;
grant insert (number,company_id,status_id,amount,revenue,description) on api.application to applicant;
grant update (number,status_id,amount,revenue,description) on api.application to applicant;
grant delete on api.application to applicant;
grant select on api.application to expert;
grant update (status_id,verdict,expert) on api.application to expert;

-- RLS
alter table api.application enable row level security;
alter table api.company enable row level security;
create policy app_admin on api.application for all to fund_admin using (true) with check (true);
create policy app_a_sel on api.application for select to applicant using (company_id=private.my_company());
create policy app_a_ins on api.application for insert to applicant with check (company_id=private.my_company());
create policy app_a_upd on api.application for update to applicant using (company_id=private.my_company() and private.ord(status_id)<3) with check (company_id=private.my_company() and private.ord(status_id)<3);
create policy app_a_del on api.application for delete to applicant using (company_id=private.my_company() and private.ord(status_id)=1);
create policy app_e_sel on api.application for select to expert using (private.ord(status_id)>=2);
create policy app_e_upd on api.application for update to expert using (private.ord(status_id)>=2) with check (private.ord(status_id)>=2);
create policy co_admin on api.company for all to fund_admin using (true) with check (true);
create policy co_exp on api.company for select to expert using (true);
create policy co_app on api.company for select to applicant using (id=private.my_company());

